p[6] = "หากเป็นการถามความจริงจากลีออน นางจะมีเวลาเพียงแค่นาทีเดียวเท่านั้น หากล่วงเลยไปกว่านั้น เขาจะไม่ตอบสนองอีก"
p[7] = "ทว่า หากเป็นการสั่งให้เขารับคำท้า ตัดสินจากสถานการณ์ปัจจุบัน ลีออนจะไม่มีทางหยุดจนกว่าจะบรรลุเป้าหมายของคำท้านั้น"
p[13] = "เมื่อไม่นานมานี้ หลังจากปลุกสัญชาตญาณกระหายเลือดของนาง ลีออนก็พานางมาที่นี่เป็นจุดแรกของ 'การผจญภัยในพงไพร' ของพวกเขา"
p[14] = "เขาอ้างว่านี่เป็นการปฏิบัติต่อนางเฉกเช่นเดียวกับที่นางเคยกระทำกับเขาในป่านอกจักรวรรดิ บัดนี้ เขาต้องการเอาคืนต่อหน้านางที่วิหารมังกรเงิน"
p[16] = "นางดึงสติกลับมาแล้วก้าวเดินตามลีออนเข้าไปในป่าซากุระ"
p[20] = "ในเมื่อรูปไม่ได้ซ่อนอยู่ที่นี่ นางจึงจำต้องเดินตามเขาต่อไป"
p[22] = "สถานที่แห่งนี้สร้างความทรงจำอันฝังลึกให้แก่รอสวิธา มันคือจุดสังเกตแห่งที่สองหลังจากที่นางและลีออนย่างกรายเข้าสู่ป่าซากุระ"
p[24] = "รอสวิธาลอบถอนหายใจเบาๆ สลัดศีรษะเพื่อขับไล่ภาพความหลังและอารมณ์สับสนออกไป นางจับจ้องมองลีออนที่ยังคงสาวเท้าเดินหน้าต่อโดยไม่มีทีท่าว่าจะหยุดพัก"
p[27] = "ทุกหนแห่งที่ลีออนพานางย่างกรายผ่าน ล้วนเป็นหนึ่งในสมรภูมิเดิมจากการศึกในป่าครั้งนั้น—ซ้ำยังเดินย้อนรอยตามลำดับเดิมเป๊ะๆ!"
p[30] = '"ยิ่งบินสูงเท่าไหร่ เวลาตกลงมาก็ยิ่งเจ็บปวดมากเท่านั้น ฮึ ดื่มด่ำกับความฝันอันแสนหวานไปก่อนเถอะพ่อนักล่ามังกร อีกประเดี๋ยวเจ้าก็จะได้ตื่นมาพบกับความจริงอันโหดร้าย!" หัวใจของราชินีมังกรเงินกระตุกวูบขณะที่ยังคงก้าวเท้าตามเขาต่อไป'
p[39] = "ทว่าลีออนกลับไม่ได้ขยับตัวค้นหาที่ใดเลย เขายังคงยืนนิ่งสงบโดยหันหลังให้นาง"
p[42] = "บุรุษเบื้องหน้าเหยียบย่ำลงบนเศษใบไม้ ค่อยๆ เอี้ยวตัวหันกลับมา ภายใต้แสงจันทร์กระจ่างตา ใบหน้าคมคายหล่อเหลาของเขาประดับไปด้วยรอยยิ้มเยาะหยัน"
p[44] = "เขาไม่ได้หลับเลยสักนิด! และไม่ได้ละเมอทำตามคำสั่งการผจญภัยอะไรทั้งนั้น เขาเพียงแต่แกล้งเล่นละครตามน้ำไปกับนางตลอดเวลา!"
p[45] = "ความว่าง่ายว่านอนสอนง่ายของเขาเป็นเพียงกับดักลวงตา ทันทีที่สบโอกาส เขาจะตอบโต้เอาคืนอย่างสาสม"
p[46] = "ราชินีผู้โชคร้ายซึ่งถูกนักล่ามังกรจอมเจ้าเล่ห์ปั่นหัวจนหมุนคว้าง รู้สึกถึงความจนตรอกอย่างถึงที่สุด ความยอมจำนนของเขาเป็นเพียงฉากบังหน้า และไม่ว่านางจะดิ้นรนเพียงใด ก็ไม่อาจหลุดพ้นจากเงื้อมมือของเขาได้เลย"
p[47] = "ถึงกระนั้น นางก็จำต้องกล้ำกลืนความพ่ายแพ้นี้ไว้ในอก เพื่อแปรเปลี่ยนเป็นแรงผลักดันในการชำระแค้นวันข้างหน้า"
p[48] = "ความล้มเหลวคือมารดาแห่งความสำเร็จ ดั่งสุภาษิตที่ว่า สามสิบปีน้ำไหลขึ้นตะวันออก สามสิบปีน้ำไหลลงตะวันตก รอสวิธาไม่เชื่อหรอกว่าตนเองจะไม่มีวันทวงคืนอำนาจกลับมาได้!"
p[49] = "ร่างบางซวนเซถอยหลังไปสองก้าว แผ่นหลังแนบพิงลำต้นของต้นป็อปลาร์"
p[51] = "บุรุษผู้กุมชะตากรรมของนางไว้ในกำมือค่อยๆ ย่างสามขุมเข้ามาใกล้ เหยียบย่ำเศษใบป็อปลาร์แห้งกรอบ เสียงกรอบแกรบของใบไม้ใต้ฝ่าเท้า ดั่งเสียงหัวใจอันเข้มแข็งของรอสวิธาที่แหลกสลายลง"
p[52] = "ลีออนหยุดยืนอยู่เบื้องหน้ารอสวิธา กวาดสายตามองนางด้วยสีหน้าคล้ายจะขัน พลางหลุดหัวเราะในลำคอเบาๆ"
p[57] = "อาจารย์ของเขาคงจงใจปิดบังเรื่องนี้ไว้ เช่นเดียวกับที่รอสวิธาปิดปากเงียบ เพื่อหลอกใช้ให้เขาช่วยทำงานบ้าน ฉะนั้นนางจึงยังไม่อาจแพร่งพรายเรื่องนี้ออกไปได้ หากบอกไป ลีออนคงหาทางเอาชนะจุดอ่อนอันพิลึกพิลั่นนี้ของตนเองอย่างแน่นอน"
p[59] = "แม้ในเวลานี้นางกำลังตกเป็นเบี้ยล่าง ทว่าราชินีมังกรเงินก็ยังคงเยือกเย็น วางแผนการอย่างรอบคอบรัดกุม"
p[61] = "รอสวิธาที่ไร้หนทางหนี เอนแผ่นหลังแนบชิดกับลำต้นไม้ เมื่อลีออนก้าวเข้ามายืนประชิดตรงหน้า นางจึงสัมผัสได้ถึงไอลมหายใจอุ่นผะผ่าวของเขา"
p[63] = "อันที่จริง การที่เขาพานางย้อนรอยกลับมายังจุดตรวจเหล่านี้มิใช่เรื่องบังเอิญหรืออารมณ์ชั่ววูบ หากแต่จงใจออกแบบมาเพื่อกระตุ้นความทรงจำอันวาบหวามของนางโดยเฉพาะ"
p[64] = "คิดได้ดังนั้น รอสวิธาก็สะบัดหน้าหนี ทว่าลีออนกลับยื่นมือมาเชยคางมน บังคับให้นางหันกลับมาสบตากับเขา"
p[66] = 'ในเมื่อมารยาของนางถูกลีออนฉีกหน้ากากจนหมดเปลือก รอสวิธาจึงไม่เห็นความจำเป็นต้องเสแสร้งแกล้งทำเป็นสาวน้อยไร้เดียงสาอีกต่อไป "ข้าไม่ชอบเลยสักที่ โดยเฉพาะตรงนี้!"'
p[70] = "ยังไม่ทันที่รอสวิธาจะได้เอ่ยคำใด ฝ่ามือใหญ่และอบอุ่นของลีออนก็โอบรัดเอวคอดกิ่วของนางไว้ แล้วดึงร่างบางเข้าสู่อ้อมอกแกร่งอย่างนุ่มนวล"
p[71] = "จากนั้น ริมฝีปากของเขาก็ประกบแนบชิดลงบนกลีบปากอิ่ม มอบจุมพิตอันดูดดื่มและเร่าร้อนเกินต้านทาน"
p[74] = "ในเมื่อขัดขืนไปก็ไร้ประโยชน์ นางจึงเลือกที่จะปล่อยใจให้เพลิดเพลินไปกับอ้อมกอดอันอบอุ่นก่อนที่พายุคลื่นลมลูกใหญ่จะซัดกระหน่ำ"
p[75] = "ท้ายที่สุดแล้ว นับแต่ลีออนปลดล็อกทักษะการจูบ เขาก็มักจะอ่อนโยนเสมอเวลาที่มอบจุมพิตให้นาง ไม่เหมือนภาพจำของ 'ราชามังกรจอมเผด็จการ' ที่ดุดันป่าเถื่อนเลยแม้แต่น้อย"
p[78] = "ร่างบอบบางของโฉมงามทอดกายลงบนฟูกใบไม้ ชิ้นส่วนสีทองกระจัดกระจาย เรือนผมสีเงินสยายพริ้วไปตามเศษใบไม้ ดั่งพู่ไหมสีเงินยามอาทิตย์อัสดง"
p[81] = "ขณะที่ริมฝีปากขบกัดใบไม้นั้นเบาๆ มันคล้ายจะเป็นสัญญาณเปิดฉากเกมรักบทใหม่ที่เร่าร้อนยิ่งกว่าเดิม..."

